		//#region \0webui-css:D:\AI\Dsh\dsh-webui\src\client\markdown\styles.css.mjs
		const tagId = "@dsh-external/dsh-webui/styles.css";
		if (document.querySelector(`style[data-plugin-css="${tagId}"]`) === null) {
			const tag = document.createElement("style");
			tag.dataset.plugin = "@dsh-external/dsh-webui";
			tag.dataset.pluginCss = tagId;
			tag.textContent = ".dsh-better-markdown__root {\r\n  display: flex;\r\n  flex-direction: column;\r\n  color: var(--dsw-alias-label-primary);\r\n  font-size: 16px;\r\n  line-height: 28px;\r\n}\r\n\r\n.dsh-better-markdown__body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 16px;\r\n}\r\n\r\n/* Card wrapper around the assistant's finalized reply content. */\r\n.dsh-better-markdown__card {\r\n  min-width: 0;\r\n  border: 1px solid var(--dsw-alias-border-base, rgba(127,127,127,.25));\r\n  border-radius: 10px;\r\n  background: rgba(127, 127, 127, .06);\r\n  padding: 12px 14px;\r\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .05);\r\n}\r\n\r\n@media (prefers-color-scheme: dark) {\r\n  .dsh-better-markdown__card {\r\n    background: rgba(255, 255, 255, .05);\r\n  }\r\n}\r\n\r\n.dsh-better-markdown__markdown {\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n  color: var(--dsw-alias-label-primary);\r\n  font: var(--dsw-font-markdown-base);\r\n}\r\n\r\n.dsh-better-markdown__markdown .markstream-react {\r\n  color: inherit;\r\n  font: inherit;\r\n}\r\n\r\n.dsh-better-markdown__markdown .node-slot:first-child :where(h1, h2, h3, h4, h5, h6, p, ul, ol, pre, blockquote) {\r\n  margin-top: 0;\r\n}\r\n\r\n.dsh-better-markdown__markdown .node-slot:last-child :where(h1, h2, h3, h4, h5, h6, p, ul, ol, pre, blockquote) {\r\n  margin-bottom: 0;\r\n}\r\n\r\n.dsh-better-markdown__markdown a {\r\n  color: var(--dsw-alias-state-business-primary);\r\n}\r\n\r\n.dsh-better-markdown__markdown :not(pre) > code {\r\n  border-radius: 6px;\r\n  background: var(--dsw-alias-markdown-inline-code);\r\n  padding: 0 5px;\r\n  color: inherit;\r\n  font: var(--dsw-font-markdown-code);\r\n  font-family: var(--ds-font-family-code);\r\n  font-size: 0.875em;\r\n}\r\n\r\n/* Markstream tables render only a faint bottom border per row — give them\r\n   proper grid lines so a table actually reads as a table. */\r\n.dsh-better-markdown__markdown table,\r\n.dsh-better-markdown__card table {\r\n  border-collapse: collapse;\r\n  border: 1px solid var(--dsw-alias-border-base, rgba(127,127,127,.35));\r\n}\r\n\r\n.dsh-better-markdown__markdown th,\r\n.dsh-better-markdown__markdown td,\r\n.dsh-better-markdown__card th,\r\n.dsh-better-markdown__card td {\r\n  border: 1px solid var(--dsw-alias-border-base, rgba(127,127,127,.35));\r\n  padding: 6px 10px;\r\n}\r\n\r\n.dsh-better-markdown__markdown thead th,\r\n.dsh-better-markdown__card thead th {\r\n  background: rgba(127,127,127,.08);\r\n  font-weight: 600;\r\n}\r\n\r\n.dsh-better-markdown__file-mention {\r\n  margin: 0;\r\n  border: 0;\r\n  padding: 0;\r\n  background: none;\r\n  color: var(--dsw-alias-state-business-primary);\r\n  cursor: pointer;\r\n  font: inherit;\r\n}\r\n\r\n.dsh-better-markdown__file-mention:hover,\r\n.dsh-better-markdown__file-mention:focus {\r\n  outline: none;\r\n  text-decoration: underline;\r\n  text-underline-offset: 3px;\r\n}\r\n\r\n.dsh-better-markdown__image {\r\n  display: block;\r\n  width: auto;\r\n  max-width: 100%;\r\n  height: auto;\r\n  border-radius: 8px;\r\n  background: var(--dsw-alias-bg-base);\r\n  object-fit: contain;\r\n}\r\n\r\n.dsh-better-markdown__image-alt {\r\n  color: var(--dsw-alias-label-tertiary);\r\n  font-style: italic;\r\n}\r\n\r\n.dsh-better-markdown__stopped {\r\n  align-self: flex-start;\r\n  border-radius: 6px;\r\n  padding: 0 6px;\r\n  background: var(--dsw-alias-interactive-bg-hover);\r\n  color: var(--dsw-alias-label-tertiary);\r\n  font-size: 11px;\r\n  line-height: 18px;\r\n}\r\n\r\n.dsh-better-markdown__reasoning {\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-row {\r\n  position: relative;\r\n  overflow: hidden;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-leading {\r\n  flex-shrink: 0;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-chevron {\r\n  color: var(--dsw-alias-label-secondary);\r\n}\r\n\r\n.dsh-better-markdown__reasoning-title {\r\n  font-weight: 400;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-separator {\r\n  width: 2px;\r\n  height: 2px;\r\n  flex: none;\r\n  margin: 0 8px;\r\n  border-radius: 1px;\r\n  background: var(--dsw-alias-label-caption);\r\n}\r\n\r\n.dsh-better-markdown__reasoning-summary {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  flex: 1 1 auto;\r\n  color: var(--dsw-alias-label-tertiary);\r\n  font-size: 14px;\r\n  line-height: 24px;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-body {\r\n  padding: 4px 0 4px 22px;\r\n  color: var(--dsw-alias-label-tertiary);\r\n  font-size: 14px;\r\n  line-height: 24px;\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-group-body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n  max-height: 320px;\r\n  overflow-y: auto;\r\n  padding: 4px 0 4px 22px;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-item {\r\n  color: var(--dsw-alias-label-tertiary);\r\n  font-size: 14px;\r\n  line-height: 24px;\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-item[data-running=\"true\"] {\r\n  color: var(--dsw-alias-label-secondary);\r\n}\r\n\r\n.dsh-better-markdown__reasoning-item + .dsh-better-markdown__reasoning-item {\r\n  border-top: 1px solid var(--dsw-alias-border-base, rgba(127,127,127,.18));\r\n  padding-top: 8px;\r\n}\r\n\r\n.dsh-better-markdown__visually-hidden {\r\n  position: absolute;\r\n  width: 1px;\r\n  height: 1px;\r\n  overflow: hidden;\r\n  margin: -1px;\r\n  clip: rect(0 0 0 0);\r\n  white-space: nowrap;\r\n}\r\n\r\n/* reasoning entry chip (opens the activity drawer) */\r\n.dsh-better-markdown__reasoning-entry {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: flex-start;\r\n  gap: 6px;\r\n  max-width: 100%;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-entry-btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  margin: 0;\r\n  border: 1px solid var(--dsw-alias-border-base, rgba(127,127,127,.25));\r\n  border-radius: 999px;\r\n  padding: 2px 12px;\r\n  background: var(--dsw-alias-bg-layer-1, rgba(127,127,127,.06));\r\n  color: var(--dsw-alias-label-secondary);\r\n  cursor: pointer;\r\n  font-size: 12px;\r\n  line-height: 22px;\r\n  white-space: nowrap;\r\n}\r\n\r\n.dsh-better-markdown__reasoning-entry-btn:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(127,127,127,.12));\r\n  color: var(--dsw-alias-label-primary);\r\n}\r\n\r\n.dsh-better-markdown__reasoning-entry[data-running=\"true\"] .dsh-better-markdown__reasoning-entry-btn {\r\n  color: var(--dsw-alias-state-business-primary, #3182ce);\r\n  border-color: color-mix(in srgb, var(--dsw-alias-state-business-primary, #3182ce) 45%, transparent);\r\n}\r\n\r\n.dsh-better-markdown__reasoning-entry-icon {\r\n  font-size: 12px;\r\n}\r\n\r\n/* live thinking preview: streams the latest reasoning text, auto-scrolls to\r\n   the newest line, and adapts its width to the transcript column. */\r\n.dsh-better-markdown__reasoning-live {\r\n  align-self: stretch;\r\n  max-height: 180px;\r\n  overflow-y: auto;\r\n  padding: 8px 12px;\r\n  border: 1px solid var(--dsw-alias-border-base, rgba(127,127,127,.2));\r\n  border-radius: 8px;\r\n  background: var(--dsw-alias-bg-layer-2, rgba(127,127,127,.04));\r\n  color: var(--dsw-alias-label-secondary);\r\n  font-size: 12px;\r\n  line-height: 20px;\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n  scrollbar-width: thin;\r\n}\r\n\r\n/* Hide markstream's \"reset font size\" toolbar button while it is disabled.\r\n   markstream disables that button whenever the code font size equals the\r\n   default (nothing to reset), which previously left an unclickable gray\r\n   button between \"shrink\" (−) and \"grow\" (+). Once the user changes the\r\n   font size the button becomes enabled and reappears. The reset button is\r\n   always the 3rd `.code-action-btn` child of the buttons row. */\r\n.dsh-better-markdown__markdown .code-block-header .code-action-btn:disabled:nth-child(3) {\r\n  display: none;\r\n}\r\n\r\n/* ============================================================\r\n   丰富的 Markdown 排版（全部用主题 token，深浅主题自适应）\r\n   ============================================================ */\r\n\r\n/* 标题：DSH markdown 字号 token + 清晰层级 */\r\n.dsh-better-markdown__markdown .heading-node {\r\n  margin: 1.4em 0 0.6em;\r\n  color: var(--dsw-alias-label-primary);\r\n  letter-spacing: -0.01em;\r\n}\r\n\r\n.dsh-better-markdown__markdown .heading-1 { font: var(--dsw-font-markdown-h1); }\r\n.dsh-better-markdown__markdown .heading-2 { font: var(--dsw-font-markdown-h2); }\r\n.dsh-better-markdown__markdown .heading-3 { font: var(--dsw-font-markdown-h3); }\r\n.dsh-better-markdown__markdown .heading-4,\r\n.dsh-better-markdown__markdown .heading-5,\r\n.dsh-better-markdown__markdown .heading-6 {\r\n  font: var(--dsw-font-markdown-h4);\r\n}\r\n\r\n/* h1/h2 底部细分隔线，层级更明显 */\r\n.dsh-better-markdown__markdown .heading-1,\r\n.dsh-better-markdown__markdown .heading-2 {\r\n  padding-bottom: 0.35em;\r\n  border-bottom: 1px solid var(--dsw-alias-border-l2, rgba(127, 127, 127, .2));\r\n}\r\n\r\n/* 引用块：左侧色条 + 淡背景 + 圆角 */\r\n.dsh-better-markdown__markdown .blockquote-node {\r\n  margin: 0.9em 0;\r\n  padding: 0.55em 1.1em;\r\n  border-left: 3px solid var(--dsw-alias-state-business-primary, #3182ce);\r\n  border-radius: 0 8px 8px 0;\r\n  background: color-mix(in srgb, var(--dsw-alias-state-business-primary, #3182ce) 7%, transparent);\r\n  color: var(--dsw-alias-label-secondary);\r\n}\r\n\r\n.dsh-better-markdown__markdown .blockquote-node > * {\r\n  margin-top: 0.3em;\r\n  margin-bottom: 0.3em;\r\n}\r\n\r\n.dsh-better-markdown__markdown .blockquote-node > :first-child { margin-top: 0; }\r\n.dsh-better-markdown__markdown .blockquote-node > :last-child { margin-bottom: 0; }\r\n\r\n/* 列表：彩色 marker + 任务复选框 */\r\n.dsh-better-markdown__markdown .list-node > li::marker {\r\n  color: var(--dsw-alias-label-tertiary);\r\n}\r\n\r\n.dsh-better-markdown__markdown .checkbox-input {\r\n  accent-color: var(--dsw-alias-state-business-primary, #3182ce);\r\n}\r\n\r\n/* 表格：斑马纹 + 悬停高亮（表头样式见上文） */\r\n.dsh-better-markdown__markdown .table-node tbody tr:nth-child(even) {\r\n  background: color-mix(in srgb, var(--dsw-alias-interactive-bg-hover, rgba(127, 127, 127, .06)) 55%, transparent);\r\n}\r\n\r\n.dsh-better-markdown__markdown .table-node tbody tr:hover {\r\n  background: var(--dsw-alias-interactive-bg-hover, rgba(127, 127, 127, .08));\r\n}\r\n\r\n/* 分隔线 */\r\n.dsh-better-markdown__markdown .thematic-break-node {\r\n  margin: 1.6em 0;\r\n  border: 0;\r\n  border-top: 1px solid var(--dsw-alias-border-l3, rgba(127, 127, 127, .2));\r\n}\r\n\r\n/* 链接：主题色下划线 + hover 加深 */\r\n.dsh-better-markdown__markdown a {\r\n  text-decoration: underline;\r\n  text-underline-offset: 2px;\r\n  text-decoration-color: color-mix(in srgb, var(--dsw-alias-state-business-primary, #3182ce) 45%, transparent);\r\n}\r\n\r\n.dsh-better-markdown__markdown a:hover {\r\n  text-decoration-color: currentColor;\r\n}\r\n\r\n/* 行内代码：细边框，更易识别 */\r\n.dsh-better-markdown__markdown :not(pre) > code {\r\n  border: 1px solid var(--dsw-alias-border-l2, rgba(127, 127, 127, .18));\r\n}\r\n\r\n/* 高亮（==mark==）：琥珀色底 */\r\n.dsh-better-markdown__markdown .highlight-node {\r\n  padding: 0 3px;\r\n  border-radius: 4px;\r\n  background: color-mix(in srgb, var(--dsw-alias-state-warn-primary, #f59e0b) 24%, transparent);\r\n  color: inherit;\r\n}\r\n\r\n/* 插入（++ins++）：绿色，保留语义 */\r\n.dsh-better-markdown__markdown .insert-node {\r\n  padding: 0 3px;\r\n  border-radius: 4px;\r\n  background: color-mix(in srgb, var(--dsw-alias-state-success-primary, #2f9e44) 14%, transparent);\r\n  color: var(--dsw-alias-state-success-primary, #2f9e44);\r\n  text-decoration: none;\r\n}\r\n\r\n/* 删除线：弱化颜色 */\r\n.dsh-better-markdown__markdown .strikethrough-node {\r\n  color: var(--dsw-alias-label-tertiary);\r\n}\r\n\r\n/* 图片：圆角 + 轻阴影 */\r\n.dsh-better-markdown__image {\r\n  box-shadow: 0 2px 10px rgba(0, 0, 0, .08);\r\n}\r\n";
			document.head.appendChild(tag);
		}
