		/**
		* DeepSeek 峰谷时刻 —— 时间逻辑（纯函数，无副作用）。
		*
		* 按 DeepSeek V4 峰谷定价：高峰时段为工作日 09:00–12:00 与 14:00–18:00
		* （北京时间），其余时间（夜间、午休、周末）为低谷时段。时区固定为
		* Asia/Shanghai（UTC+8，无夏令时）。
		*/
		const SHANGHAI_OFFSET_MS = 480 * 60 * 1e3;
		/** 取当前时刻的北京时间墙钟（用 UTC getter 读取偏移后的日期，避开本机时区）。 */
		function beijingClock(nowMs) {
			const d = new Date(nowMs + SHANGHAI_OFFSET_MS);
			return {
				day: d.getUTCDay(),
				hour: d.getUTCHours(),
				minute: d.getUTCMinutes()
			};
		}
		const isWeekday = (day) => day >= 1 && day <= 5;
		/** 当前是否处于高峰时段（工作日 09:00–12:00 / 14:00–18:00，左闭右开）。 */
		function isPeak(day, hour, minute) {
			if (!isWeekday(day)) return false;
			const t = hour * 60 + minute;
			return t >= 540 && t < 720 || t >= 840 && t < 1080;
		}
		/** 以周一 00:00 为 0 的一周分钟数（Mon=0 … Sun=6）。 */
		function minuteOfWeek(day, hour, minute) {
			return (day + 6) % 7 * 1440 + hour * 60 + minute;
		}
		/** 一周内的全部峰谷切换点（工作日 × 09:00/12:00/14:00/18:00）。 */
		const WEEK_TRANSITIONS = (() => {
			const out = [];
			for (let d = 0; d <= 4; d++) {
				const base = d * 1440;
				out.push({
					minute: base + 540,
					to: "peak"
				});
				out.push({
					minute: base + 720,
					to: "off"
				});
				out.push({
					minute: base + 840,
					to: "peak"
				});
				out.push({
					minute: base + 1080,
					to: "off"
				});
			}
			return out;
		})();
		const WEEK_MINUTES = 7 * 1440;
		/** 下一段峰/谷切换：目标状态 + 距当前的分钟数。 */
		function nextTransition(clock) {
			const now = minuteOfWeek(clock.day, clock.hour, clock.minute);
			for (const t of WEEK_TRANSITIONS) if (t.minute > now) return {
				to: t.to,
				deltaMinutes: t.minute - now
			};
			return {
				to: "peak",
				deltaMinutes: WEEK_MINUTES - now + 540
			};
		}
		/** 分钟数 → 可读时长（不足 1 小时显示分钟，整点省略分钟）。 */
		function formatDelta(minutes) {
			if (minutes <= 0) return "0 分钟";
			if (minutes < 60) return `${minutes} 分钟`;
			const h = Math.floor(minutes / 60);
			const m = minutes % 60;
			return m === 0 ? `${h} 小时` : `${h} 小时 ${m} 分`;
		}
